(() => {
'use strict';
const VERSION='0.1.0'; const STATE_KEY='state.v1';
const WODS=Array.isArray(window.WLC_EMBEDDED_WODS)?window.WLC_EMBEDDED_WODS:[];
const WEIGHTLIFTING=['Strappo','Strappo in accosciata','Power Snatch','Hang Snatch','Muscle Snatch','Snatch Balance','Slancio','Girata','Power Clean','Hang Clean','Clean & Jerk','Spinta','Split Jerk','Power Jerk','Squat Jerk','Front Squat','Back Squat','Overhead Squat','Stacco','Stacco strappo','Stacco slancio','Tirata strappo','Tirata slancio','Push Press','Military Press','Good Morning','Romanian Deadlift','Rematore'];
const CROSSFIT=['Air Squat','Wall Ball','Thruster','Cluster','Sumo Deadlift High Pull','Pull-up','Strict Pull-up','Chest to Bar','Bar Muscle-up','Ring Muscle-up','Ring Dip','Toes to Bar','Knees to Elbows','Hanging Leg Raise','Handstand Push-up','Strict Handstand Push-up','Handstand Walk','Rope Climb','Legless Rope Climb','Pistol Squat','Burpee','Burpee Over Bar','Burpee Box Jump','Burpee Box Jump Over','Burpee Broad Jump','Burpee Pull-up','Box Jump','Box Jump Over','Box Step-up','Dumbbell Snatch','Dumbbell Clean & Jerk','Dumbbell Thruster','Devil Press','Kettlebell Swing','American Kettlebell Swing','Russian Kettlebell Swing','Goblet Squat','Turkish Get-up','Farmer Carry','Sandbag Carry','Sandbag Clean','Sled Push','Sled Pull','Corsa','Row','BikeErg','Assault Bike','Echo Bike','SkiErg','Nuoto','Double Under','Single Under','Plank','Side Plank','Hollow Hold','Arch Hold','Dead Bug','Sit-up','Crunch','Russian Twist','Back Extension','GHD Sit-up','Pallof Press'];
const EXERCISES=Array.from(new Set([...WEIGHTLIFTING,...CROSSFIT])).sort((a,b)=>a.localeCompare(b,'it'));
const ALIASES={'Strappo':['Snatch','Olympic Snatch'],'Strappo in accosciata':['Squat Snatch','Full Snatch'],'Stacco':['Deadlift'],'Stacco strappo':['Snatch Deadlift'],'Stacco slancio':['Clean Deadlift'],'Girata':['Clean','Squat Clean'],'Slancio':['Clean and Jerk','Clean & Jerk'],'Power Clean':['Girata in Power'],'Power Snatch':['Strappo in Power'],'Pull-up':['Pullups','Trazioni'],'Chest to Bar':['C2B','Chest-to-bar'],'Bar Muscle-up':['BMU','Bar Muscle Up'],'Ring Muscle-up':['RMU','Ring Muscle Up'],'Handstand Push-up':['HSPU'],'Handstand Walk':['HSW'],'Toes to Bar':['T2B'],'Double Under':['DU','Double Unders'],'Dumbbell Snatch':['DB Snatch'],'Dumbbell Clean & Jerk':['DB Clean and Jerk','DB Clean & Jerk'],'Burpee Over Bar':['Bar Facing Burpee','Burpees Over Bar'],'Burpee Box Jump Over':['BBJO'],'Row':['Rower','Remoergometro'],'Assault Bike':['Air Bike']};
const SECTION_META={warmup:{title:'Riscaldamento',emoji:'🔥'},tabata:{title:'Tabata',emoji:'🎵'},skill:{title:'Skill',emoji:'🤸🏻‍♀️'},strength:{title:'Forza',emoji:'💪'},weightlifting:{title:'Pesistica',emoji:'🏋️'},metcon:{title:'Metcon',emoji:'🏃'},wod:{title:'WOD',emoji:'💥'},core:{title:'Core / Accessory',emoji:'🧱'},cooldown:{title:'Cooldown',emoji:'🧘'},custom:{title:'Sezione',emoji:'✦'}};
const app=document.getElementById('app'), modalBackdrop=document.getElementById('modalBackdrop'), modalTitle=document.getElementById('modalTitle'),modalSubtitle=document.getElementById('modalSubtitle'),modalBody=document.getElementById('modalBody'),toast=document.getElementById('toast'),suggestions=document.getElementById('suggestions'),backupInput=document.getElementById('backupInput');
let state=null, view={screen:'home'}, calendarCursor=startMonth(new Date()), toastTimer=null, activeSuggestionInput=null;

function uid(prefix='id'){return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,9)}`}
function esc(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;')}
function todayISO(){return localISO(new Date())} function localISO(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function parseISO(v){if(!v)return new Date();const [y,m,d]=v.split('-').map(Number);return new Date(y,(m||1)-1,d||1,12)} function startMonth(d){return new Date(d.getFullYear(),d.getMonth(),1,12)}
function fmtDate(v,opts={day:'2-digit',month:'2-digit',year:'numeric'}){return v?new Intl.DateTimeFormat('it-IT',opts).format(parseISO(v)):'—'} function fmtLong(v){return fmtDate(v,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}
function daysUntil(v){return Math.round((parseISO(v)-parseISO(todayISO()))/86400000)}
function age(b){if(!b)return null;const d=parseISO(b),n=new Date();let a=n.getFullYear()-d.getFullYear();if(n.getMonth()<d.getMonth()||(n.getMonth()===d.getMonth()&&n.getDate()<d.getDate()))a--;return a}
function freshState(){return {schema:1,appVersion:VERSION,profile:{id:uid('athlete'),firstName:'',lastName:'',birthDate:'',sex:'female',discipline:'both'},weights:[],records:[],wodRecords:[],workouts:[],competitions:[],rests:[],personalWods:[],settings:{createdAt:new Date().toISOString(),futureSync:{enabled:false,coachLinkId:''}}}}
function normalize(s){const b=freshState();if(!s||typeof s!=='object')return b;return {...b,...s,profile:{...b.profile,...(s.profile||{})},weights:Array.isArray(s.weights)?s.weights:[],records:Array.isArray(s.records)?s.records:[],wodRecords:Array.isArray(s.wodRecords)?s.wodRecords:[],workouts:Array.isArray(s.workouts)?s.workouts:[],competitions:Array.isArray(s.competitions)?s.competitions:[],rests:Array.isArray(s.rests)?s.rests:[],personalWods:Array.isArray(s.personalWods)?s.personalWods:[],settings:{...b.settings,...(s.settings||{})}}}
async function save(){state.appVersion=VERSION;await TJDB.set(STATE_KEY,state)}
function name(){const n=`${state.profile.firstName||''} ${state.profile.lastName||''}`.trim();return n||'Atleta'}
function latestWeight(){return [...state.weights].sort((a,b)=>String(b.date).localeCompare(String(a.date)))[0]||null}
function nextCompetition(){return [...state.competitions].filter(c=>daysUntil(c.date)>=0).sort((a,b)=>a.date.localeCompare(b.date))[0]||null}
function showToast(msg){toast.textContent=msg;toast.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.add('hidden'),2200)}
function setView(screen,params={}){view={screen,...params};render();window.scrollTo({top:0,behavior:'instant'})}
function activeNav(){if(['day','workout','workout-edit','workout-log','competition-edit'].includes(view.screen))return view.screen==='competition-edit'?'competitions':'calendar';return view.screen}
function updateNav(){document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===activeNav()));const sub=document.getElementById('mobileSubtitle');if(sub)sub.textContent=({home:'Oggi',calendar:'Calendario',progress:'Progressi',competitions:'Gare',profile:'Profilo'})[activeNav()]||'Training Journal'}
function openModal(title,html,subtitle=''){modalTitle.textContent=title;modalSubtitle.textContent=subtitle;modalBody.innerHTML=html;modalBackdrop.classList.remove('hidden');document.body.style.overflow='hidden';setTimeout(()=>{const x=modalBody.querySelector('input,select,textarea,button');if(x)x.focus()},40)}
function closeModal(){modalBackdrop.classList.add('hidden');modalBody.innerHTML='';document.body.style.overflow='';hideSuggestions()}
function empty(icon,title,text,button='',action=''){return `<div class="empty"><div class="icon">${icon}</div><h3>${esc(title)}</h3><p>${esc(text)}</p>${button?`<button class="button" data-action="${action}">${esc(button)}</button>`:''}</div>`}
function canonicalExercise(v){const q=String(v||'').trim();if(!q)return '';for(const [canon,als] of Object.entries(ALIASES)){if(canon.toLowerCase()===q.toLowerCase()||als.some(a=>a.toLowerCase()===q.toLowerCase()))return canon}return q}
function searchableExercises(q){const s=String(q||'').trim().toLowerCase();if(!s)return EXERCISES.slice(0,8);const rows=[];for(const e of EXERCISES){const hay=[e,...(ALIASES[e]||[])].join(' ').toLowerCase();if(hay.includes(s))rows.push(e)}return rows.slice(0,8)}
function bindExerciseSuggestions(scope=document){scope.querySelectorAll('[data-exercise-input]').forEach(inp=>{inp.addEventListener('input',()=>showSuggestions(inp));inp.addEventListener('focus',()=>showSuggestions(inp));inp.addEventListener('blur',()=>setTimeout(hideSuggestions,180))})}
function showSuggestions(inp){activeSuggestionInput=inp;const matches=searchableExercises(inp.value);if(!matches.length){hideSuggestions();return}const r=inp.getBoundingClientRect();suggestions.style.left=`${Math.max(8,Math.min(r.left,window.innerWidth-250))}px`;suggestions.style.top=`${Math.min(r.bottom+4,window.innerHeight-250)}px`;suggestions.style.width=`${Math.max(230,Math.min(r.width,340))}px`;suggestions.innerHTML=matches.map(x=>`<button class="suggestion" data-suggestion="${esc(x)}">${esc(x)}${ALIASES[x]?`<span class="muted tiny"> · ${esc(ALIASES[x][0])}</span>`:''}</button>`).join('');suggestions.classList.remove('hidden')}
function hideSuggestions(){suggestions.classList.add('hidden');suggestions.innerHTML='';activeSuggestionInput=null}

function render(){updateNav();switch(view.screen){case'calendar':return renderCalendar();case'day':return renderDay(view.date);case'workout':return renderWorkout(view.id);case'workout-edit':return renderWorkoutEditor(view.id,view.date);case'workout-log':return renderWorkoutLog(view.id);case'progress':return renderProgress();case'competitions':return renderCompetitions();case'competition-edit':return renderCompetitionEditor(view.id,view.date);case'profile':return renderProfile();default:return renderHome()}}
function page(content){app.innerHTML=`<div class="page">${content}</div>`}
function renderHome(){const today=todayISO(),workouts=state.workouts.filter(w=>w.date===today),next=nextCompetition(),lw=latestWeight(),recentPR=[...state.records].sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,3);page(`<section class="hero"><div class="eyebrow" style="color:#f1b99f">${esc(fmtLong(today))}</div><h1>${state.profile.firstName?`Ciao, ${esc(state.profile.firstName)}`:'Il tuo diario di allenamento'}</h1><p>Pesistica, CrossFit, gare e progressi in un unico posto.</p><div class="actions"><button class="button accent" data-action="new-workout" data-date="${today}">＋ Allenamento</button><button class="button secondary" data-action="add-weight">⚖️ Peso</button></div></section>
<div class="grid four" style="margin-top:12px"><div class="card stat"><span>Peso recente</span><strong>${lw?`${fmtNum(lw.kg)} kg`:'—'}</strong><span>${lw?fmtDate(lw.date):'Non registrato'}</span></div><div class="card stat"><span>Massimali</span><strong>${state.records.length}</strong><span>record registrati</span></div><div class="card stat"><span>WOD score</span><strong>${state.wodRecords.length}</strong><span>risultati</span></div><div class="card stat"><span>Allenamenti</span><strong>${state.workouts.filter(w=>w.status==='completed').length}</strong><span>completati</span></div></div>
${next?`<h2 class="section-title">Prossima gara</h2><div class="card countdown clickable" data-nav="competitions"><strong>${daysUntil(next.date)===0?'Oggi':`${daysUntil(next.date)} giorni`}</strong><span>${esc(next.name)} · ${esc(fmtDate(next.date))}</span></div>`:''}
<h2 class="section-title">Oggi</h2>${workouts.length?`<div class="list">${workouts.map(workoutCard).join('')}</div>`:empty('▦','Nessun allenamento programmato','Puoi creare la seduta di oggi oppure usare il calendario.','Crea allenamento','new-workout')}
${recentPR.length?`<h2 class="section-title">PR recenti</h2><div class="list">${recentPR.map(r=>`<div class="list-item"><div class="avatar">🏆</div><div class="grow"><h3>${esc(r.exercise)} · ${esc(r.reps)}RM</h3><p>${fmtNum(r.kg)} kg · ${fmtDate(r.date)}</p></div></div>`).join('')}</div>`:''}`)}
function workoutCard(w){const count=(w.sections||[]).length;return `<div class="list-item clickable" data-action="open-workout" data-id="${w.id}"><div class="avatar">${w.status==='completed'?'✓':'TJ'}</div><div class="grow"><h3>${esc(w.title||'Allenamento')}</h3><p>${fmtDate(w.date)} · ${count} sezion${count===1?'e':'i'}${w.status==='completed'?' · completato':''}</p></div><span class="badge ${w.status==='completed'?'success':''}">${w.status==='completed'?'Svolto':'Programmato'}</span></div>`}
function renderCalendar(){const first=startMonth(calendarCursor),monthName=new Intl.DateTimeFormat('it-IT',{month:'long',year:'numeric'}).format(first),monIndex=(first.getDay()+6)%7,gridStart=new Date(first.getFullYear(),first.getMonth(),1-monIndex,12),days=[];for(let i=0;i<42;i++){const d=new Date(gridStart);d.setDate(gridStart.getDate()+i);days.push(d)}page(`<div class="page-head"><div><h1>Calendario</h1><p class="muted">Programmazione, sedute svolte, pesi, massimali, riposo e gare.</p></div><button class="button" data-action="new-workout" data-date="${todayISO()}">＋ Allenamento</button></div><div class="card calendar-toolbar"><button class="icon-btn" data-action="cal-prev">‹</button><h2>${esc(monthName)}</h2><button class="icon-btn" data-action="cal-next">›</button></div><div class="calendar-grid">${['Lun','Mar','Mer','Gio','Ven','Sab','Dom'].map(x=>`<div class="weekday">${x}</div>`).join('')}${days.map(d=>calendarDay(d,first.getMonth())).join('')}</div><div class="chips" style="margin-top:12px"><span class="chip">● Allenamento</span><span class="chip accent">● WOD</span><span class="chip">⚖️ Peso</span><span class="chip">🏆 Gara</span><span class="chip">💤 Riposo</span></div>`)}
function dayEvents(iso){const out=[];state.workouts.filter(w=>w.date===iso).forEach(w=>out.push({type:(w.sections||[]).some(s=>s.type==='wod'||s.type==='metcon')?'wod':'workout',label:w.title||'Allenamento'}));state.competitions.filter(c=>c.date===iso).forEach(c=>out.push({type:'competition',label:c.name}));state.weights.filter(x=>x.date===iso).forEach(()=>out.push({type:'weight',label:'Peso'}));state.records.filter(x=>x.date===iso).forEach(()=>out.push({type:'record',label:'PR'}));state.rests.filter(x=>x.date===iso).forEach(()=>out.push({type:'rest',label:'Riposo'}));return out}
function calendarDay(d,currentMonth){const iso=localISO(d),events=dayEvents(iso);return `<button class="calendar-day ${d.getMonth()!==currentMonth?'outside':''} ${iso===todayISO()?'today':''}" data-action="open-day" data-date="${iso}"><span class="day-number">${d.getDate()}</span><div class="event-dots">${events.slice(0,7).map(e=>`<span class="event-dot ${e.type}"></span>`).join('')}</div>${events.slice(0,2).map(e=>`<div class="event-label">${esc(e.label)}</div>`).join('')}</button>`}
function renderDay(date){const ws=state.workouts.filter(w=>w.date===date),cs=state.competitions.filter(c=>c.date===date),weights=state.weights.filter(x=>x.date===date),recs=state.records.filter(x=>x.date===date),rest=state.rests.find(x=>x.date===date);page(`<div class="page-head"><div><button class="button ghost small" data-nav="calendar">‹ Calendario</button><h1 style="margin-top:10px;text-transform:capitalize">${esc(fmtLong(date))}</h1></div><div class="actions"><button class="button" data-action="new-workout" data-date="${date}">＋ Allenamento</button></div></div><div class="quick-row"><button class="button secondary small" data-action="add-weight" data-date="${date}">⚖️ Peso</button><button class="button secondary small" data-action="add-record" data-date="${date}">🏆 Massimale</button><button class="button secondary small" data-action="new-competition" data-date="${date}">★ Gara</button><button class="button secondary small" data-action="toggle-rest" data-date="${date}">${rest?'✓ Riposo':'💤 Riposo'}</button></div><h2 class="section-title">Allenamenti</h2>${ws.length?`<div class="list">${ws.map(workoutCard).join('')}</div>`:empty('▦','Nessun allenamento','Crea una seduta per questa data.')}<h2 class="section-title">Altri eventi</h2><div class="list">${weights.map(x=>`<div class="list-item"><div class="avatar">⚖️</div><div class="grow"><h3>Peso corporeo</h3><p>${fmtNum(x.kg)} kg</p></div></div>`).join('')}${recs.map(r=>`<div class="list-item"><div class="avatar">🏆</div><div class="grow"><h3>${esc(r.exercise)} ${r.reps}RM</h3><p>${fmtNum(r.kg)} kg</p></div></div>`).join('')}${cs.map(c=>`<div class="list-item clickable" data-nav="competitions"><div class="avatar">★</div><div class="grow"><h3>${esc(c.name)}</h3><p>${c.type==='crossfit'?'CrossFit':'Pesistica'}</p></div></div>`).join('')}${rest?`<div class="list-item"><div class="avatar">💤</div><div class="grow"><h3>Giorno di riposo</h3><p>${esc(rest.notes||'Recupero')}</p></div></div>`:''}</div>`)}

function newSection(type){const m=SECTION_META[type]||SECTION_META.custom;const base={id:uid('sec'),type,title:m.title,emoji:m.emoji,completed:false,actualNotes:''};if(type==='warmup'||type==='core')return {...base,mode:'structured',scheme:'Rounds',amount:type==='warmup'?'3':'3',intro:'',rows:[{id:uid('row'),exercise:'',reps:'',note:''}]};if(type==='tabata')return {...base,work:'20"',rest:'10"',rounds:'8',items:['']};if(type==='skill'||type==='metcon'||type==='cooldown'||type==='custom')return {...base,mode:'free',text:''};if(type==='strength'||type==='weightlifting')return {...base,rows:[newLiftRow()]};if(type==='wod')return {...base,mode:'free',name:'',text:'',format:'',scoreType:'time',level:'Rx',libraryId:'',savePersonal:false};return base}
function newLiftRow(){return {id:uid('lift'),exercise:'',sets:'',reps:'',load:'',percent:'',rm:'1',rest:'',actualLoad:'',actualReps:'',actualSets:'',completed:false,attempts:''}}
function templateSections(name){if(name==='crossfit')return ['warmup','skill','strength','wod','cooldown'].map(newSection);if(name==='hybrid')return ['warmup','tabata','skill','metcon','wod','cooldown'].map(newSection);if(name==='wlmetcon')return ['warmup','weightlifting','strength','metcon','core'].map(newSection);return []}
function renderWorkoutEditor(id,date){const existing=id?state.workouts.find(w=>w.id===id):null;let draft=existing?JSON.parse(JSON.stringify(existing)):{id:uid('workout'),date:date||todayISO(),title:'',sections:[],status:'planned',createdAt:new Date().toISOString(),summary:{duration:'',rpe:'',notes:''}};view.draft=draft;page(`<div class="page-head"><div><button class="button ghost small" data-action="cancel-workout-edit">‹ Indietro</button><h1 style="margin-top:10px">${existing?'Modifica allenamento':'Nuovo allenamento'}</h1><p class="muted">Costruisci la seduta per sezioni. Puoi combinare Pesistica e CrossFit.</p></div><button class="button" data-action="save-workout">Salva</button></div><div class="card"><div class="form-grid two"><div class="field"><label>Data</label><input id="workoutDate" type="date" value="${esc(draft.date)}"></div><div class="field"><label>Titolo</label><input id="workoutTitle" value="${esc(draft.title)}" placeholder="Es. Hybrid Training"></div></div><div class="quick-row" style="margin-top:12px"><span class="muted small">Modelli:</span><button class="button ghost small" data-action="workout-template" data-template="crossfit">CrossFit</button><button class="button ghost small" data-action="workout-template" data-template="hybrid">Hybrid</button><button class="button ghost small" data-action="workout-template" data-template="wlmetcon">WL + Metcon</button></div></div><div class="page-head" style="margin-top:18px;margin-bottom:8px"><h2 class="section-title" style="margin:0">Sezioni</h2><div class="quick-row"><select id="sectionType" style="min-height:36px;border:1px solid var(--line);border-radius:9px;padding:5px 8px">${Object.entries(SECTION_META).map(([k,m])=>`<option value="${k}">${m.emoji} ${m.title}</option>`).join('')}</select><button class="button secondary small" data-action="add-section">＋ Sezione</button></div></div><div id="sectionEditor">${draft.sections.length?draft.sections.map((s,i)=>sectionEditorHtml(s,i)).join(''):empty('＋','Nessuna sezione','Scegli un modello oppure aggiungi manualmente Warm-up, Skill, WOD e le altre parti.')}</div><div class="actions end" style="margin-top:18px"><button class="button ghost" data-action="cancel-workout-edit">Annulla</button><button class="button" data-action="save-workout">Salva allenamento</button></div>`);bindWorkoutDraft()}
function sectionEditorHtml(s,i){const meta=SECTION_META[s.type]||SECTION_META.custom;let body='';if(s.type==='warmup'||s.type==='core'){body=`<div class="form-grid three"><div class="field"><label>Modalità</label><select data-sec-field="scheme"><option ${s.scheme==='Rounds'?'selected':''}>Rounds</option><option ${s.scheme==='Tempo'?'selected':''}>Tempo</option><option ${s.scheme==='Not For Time'?'selected':''}>Not For Time</option><option ${s.scheme==='Libero'?'selected':''}>Libero</option></select></div><div class="field"><label>Quantità / durata</label><input data-sec-field="amount" value="${esc(s.amount||'')}" placeholder="3 oppure 10'"></div><div class="field"><label>Introduzione</label><input data-sec-field="intro" value="${esc(s.intro||'')}" placeholder="Facoltativa"></div></div><table class="mini-table"><thead><tr><th>Movimento</th><th>Reps/tempo</th><th>Nota</th><th></th></tr></thead><tbody>${(s.rows||[]).map(r=>simpleRowHtml(r)).join('')}</tbody></table><button class="button ghost small" data-action="add-simple-row" data-sec="${s.id}">＋ Movimento</button>`}
else if(s.type==='tabata'){body=`<div class="form-grid three"><div class="field"><label>Lavoro</label><input data-sec-field="work" value="${esc(s.work||'20\"')}"></div><div class="field"><label>Recupero</label><input data-sec-field="rest" value="${esc(s.rest||'10\"')}"></div><div class="field"><label>Round</label><input data-sec-field="rounds" value="${esc(s.rounds||'8')}"></div></div><div class="form-grid" style="margin-top:9px">${(s.items||[]).map((x,ix)=>`<div class="quick-row"><input data-tabata-item="${ix}" value="${esc(x)}" data-exercise-input placeholder="Elemento ${String.fromCharCode(65+ix)}" style="flex:1;min-height:38px;border:1px solid var(--line);border-radius:9px;padding:7px 8px"><button class="button ghost small" data-action="remove-tabata-item" data-sec="${s.id}" data-index="${ix}">✕</button></div>`).join('')}</div><button class="button ghost small" style="margin-top:8px" data-action="add-tabata-item" data-sec="${s.id}">＋ Elemento</button>`}
else if(s.type==='strength'||s.type==='weightlifting'){body=`<table class="mini-table"><thead><tr><th>Movimento</th><th>Serie</th><th>Rep</th><th>Peso</th><th>%</th><th>RM</th><th>Rec.</th><th></th></tr></thead><tbody>${(s.rows||[]).map(r=>liftRowHtml(r)).join('')}</tbody></table><button class="button ghost small" data-action="add-lift-row" data-sec="${s.id}">＋ Riga</button>`}
else if(s.type==='wod'){body=`<div class="form-grid two"><div class="field"><label>Nome WOD</label><input data-sec-field="name" value="${esc(s.name||'')}" placeholder="Es. Fran o WOD personale"></div><div class="field"><label>Formato</label><input data-sec-field="format" value="${esc(s.format||'')}" placeholder="For Time / AMRAP / EMOM"></div><div class="field"><label>Tipo score</label><select data-sec-field="scoreType">${[['time','Tempo'],['rounds_plus_reps','Round + rep'],['reps','Ripetizioni'],['load','Carico'],['calories','Calorie'],['distance','Distanza'],['points','Punti']].map(([v,l])=>`<option value="${v}" ${s.scoreType===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Livello</label><select data-sec-field="level"><option ${s.level==='Rx'?'selected':''}>Rx</option><option ${s.level==='Rx+'?'selected':''}>Rx+</option><option ${s.level==='Scaled'?'selected':''}>Scaled</option><option ${s.level==='Personalizzato'?'selected':''}>Personalizzato</option></select></div></div><div class="quick-row" style="margin-top:9px"><button class="button secondary small" data-action="open-wod-library" data-sec="${s.id}">🔎 Importa dalla libreria</button></div><div class="field" style="margin-top:9px"><label>WOD / descrizione libera</label><textarea data-sec-field="text" style="min-height:140px" placeholder="Scrivi il WOD oppure importalo dalla libreria">${esc(s.text||'')}</textarea></div><label class="checkline" style="margin-top:8px"><input type="checkbox" data-sec-field-check="savePersonal" ${s.savePersonal?'checked':''}> Salva questo WOD nella mia libreria personale</label>`}
else{body=`<div class="field"><label>Testo libero</label><textarea data-sec-field="text" style="min-height:120px" placeholder="Scrivi liberamente il lavoro">${esc(s.text||'')}</textarea></div>`}
return `<section class="workout-section" data-section-id="${s.id}"><div class="section-head"><span class="section-emoji">${esc(s.emoji||meta.emoji)}</span><input data-sec-field="title" value="${esc(s.title||meta.title)}" style="flex:1;border:0;background:transparent;font-weight:800;outline:none"><div class="section-tools"><button class="button ghost" data-action="section-up" data-sec="${s.id}">↑</button><button class="button ghost" data-action="section-down" data-sec="${s.id}">↓</button><button class="button ghost" data-action="section-delete" data-sec="${s.id}">✕</button></div></div><div class="section-body">${body}</div></section>`}
function simpleRowHtml(r){return `<tr data-row-id="${r.id}"><td class="exercise-cell"><input data-row-field="exercise" data-exercise-input value="${esc(r.exercise||'')}" placeholder="Esercizio"></td><td><input data-row-field="reps" value="${esc(r.reps||'')}" placeholder="10 / 30\""></td><td><input data-row-field="note" value="${esc(r.note||'')}" placeholder="Nota"></td><td><button class="button ghost small" data-action="remove-row">✕</button></td></tr>`}
function liftRowHtml(r){return `<tr data-row-id="${r.id}"><td class="exercise-cell"><input data-row-field="exercise" data-exercise-input value="${esc(r.exercise||'')}" placeholder="Esercizio"></td><td><input data-row-field="sets" value="${esc(r.sets||'')}" placeholder="4"></td><td><input data-row-field="reps" value="${esc(r.reps||'')}" placeholder="3 / 1+1"></td><td><input data-row-field="load" value="${esc(r.load||'')}" placeholder="80 / 80-85"></td><td><input data-row-field="percent" value="${esc(r.percent||'')}" placeholder="%"></td><td><input data-row-field="rm" value="${esc(r.rm||'1')}" placeholder="1"></td><td><input data-row-field="rest" value="${esc(r.rest||'')}" placeholder="2'"></td><td><button class="button ghost small" data-action="remove-row">✕</button></td></tr>`}
function bindWorkoutDraft(){document.getElementById('workoutDate').addEventListener('input',e=>view.draft.date=e.target.value);document.getElementById('workoutTitle').addEventListener('input',e=>view.draft.title=e.target.value);document.querySelectorAll('[data-section-id]').forEach(el=>bindSection(el));bindExerciseSuggestions(document)}
function bindSection(el){const s=view.draft.sections.find(x=>x.id===el.dataset.sectionId);if(!s)return;el.querySelectorAll('[data-sec-field]').forEach(f=>f.addEventListener('input',()=>s[f.dataset.secField]=f.value));el.querySelectorAll('[data-sec-field-check]').forEach(f=>f.addEventListener('change',()=>s[f.dataset.secFieldCheck]=f.checked));el.querySelectorAll('[data-tabata-item]').forEach(f=>f.addEventListener('input',()=>s.items[Number(f.dataset.tabataItem)]=f.value));el.querySelectorAll('[data-row-id]').forEach(rowEl=>{const r=(s.rows||[]).find(x=>x.id===rowEl.dataset.rowId);if(!r)return;rowEl.querySelectorAll('[data-row-field]').forEach(f=>f.addEventListener('input',()=>r[f.dataset.rowField]=f.value))})}
function rerenderDraftSections(){const c=document.getElementById('sectionEditor');if(c){c.innerHTML=view.draft.sections.length?view.draft.sections.map((s,i)=>sectionEditorHtml(s,i)).join(''):empty('＋','Nessuna sezione','Aggiungi la prima sezione.');bindWorkoutDraft()}}
async function saveWorkoutDraft(){const d=view.draft;if(!d.sections.length){showToast('Aggiungi almeno una sezione');return}d.title=(d.title||'').trim()||`Allenamento ${fmtDate(d.date)}`;d.updatedAt=new Date().toISOString();for(const s of d.sections){if(s.type==='wod'&&s.savePersonal&&(s.name||s.text)){const exists=state.personalWods.find(x=>x.sourceSectionId===s.id);const p={id:exists?exists.id:uid('pwod'),sourceSectionId:s.id,name:s.name||'WOD personale',format:s.format||'',scoreType:s.scoreType||'time',description:s.text||'',createdAt:exists?exists.createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),searchText:`${s.name||''} ${s.format||''} ${s.text||''}`.toLowerCase()};if(exists)Object.assign(exists,p);else state.personalWods.push(p)}}const ix=state.workouts.findIndex(w=>w.id===d.id);if(ix>=0)state.workouts[ix]=d;else state.workouts.push(d);await save();setView('workout',{id:d.id});showToast('Allenamento salvato')}

function plannedSectionHtml(s){let c='';if(s.type==='warmup'||s.type==='core'){c=`${s.intro?`<div>${esc(s.intro)}</div>`:''}<div><strong>${esc(s.amount||'')} ${esc(s.scheme||'')}</strong></div>${(s.rows||[]).map(r=>`<div>${esc(r.reps||'')} ${esc(r.exercise||'')}${r.note?` · ${esc(r.note)}`:''}</div>`).join('')}`}
else if(s.type==='tabata'){c=`<div><strong>${esc(s.work)} lavoro / ${esc(s.rest)} recupero · ${esc(s.rounds)} round</strong></div>${(s.items||[]).filter(Boolean).map((x,i)=>`<div>${String.fromCharCode(65+i)}. ${esc(x)}</div>`).join('')}`}
else if(s.type==='strength'||s.type==='weightlifting'){c=(s.rows||[]).map(r=>`<div><strong>${esc(r.exercise||'Esercizio')}</strong> — ${esc(r.sets||'—')}×${esc(r.reps||'—')}${r.load?` @ ${esc(r.load)} kg`:''}${r.percent?` · ${esc(r.percent)}% del ${esc(r.rm||1)}RM`:''}${r.rest?` · Rec. ${esc(r.rest)}`:''}</div>`).join('')}
else if(s.type==='wod'){c=`${s.name?`<div><strong>${esc(s.name)}</strong>${s.format?` · ${esc(s.format)}`:''}</div>`:''}<div>${esc(s.text||'').replace(/\n/g,'<br>')}</div>`}
else c=esc(s.text||'').replace(/\n/g,'<br>');return `<section class="workout-section"><div class="section-head"><span class="section-emoji">${esc(s.emoji||'')}</span><strong>${esc(s.title||'Sezione')}</strong>${s.completed?'<span class="badge success">✓ svolto</span>':''}</div><div class="section-body planned-block">${c||'<span class="muted">Nessun contenuto</span>'}${s.actualNotes?`<div class="actual-panel"><strong>Svolto / note</strong><div style="margin-top:4px">${esc(s.actualNotes).replace(/\n/g,'<br>')}</div></div>`:''}</div></section>`}
function renderWorkout(id){const w=state.workouts.find(x=>x.id===id);if(!w)return setView('calendar');page(`<div class="page-head"><div><button class="button ghost small" data-action="open-day" data-date="${w.date}">‹ ${fmtDate(w.date)}</button><h1 style="margin-top:10px">${esc(w.title)}</h1><p class="muted">${esc(fmtLong(w.date))}</p></div><div class="actions"><button class="button secondary small" data-action="share-workout" data-id="${w.id}" data-mode="planned">Condividi programmato</button>${w.status==='completed'?`<button class="button secondary small" data-action="share-workout" data-id="${w.id}" data-mode="done">Condividi svolto</button>`:''}<button class="button ghost small" data-action="edit-workout" data-id="${w.id}">Modifica</button><button class="button ${w.status==='completed'?'secondary':'accent'}" data-action="log-workout" data-id="${w.id}">${w.status==='completed'?'Modifica svolto':'Inizia / registra'}</button></div></div>${w.status==='completed'?`<div class="grid three"><div class="card stat"><span>Durata</span><strong>${esc(w.summary?.duration||'—')}</strong></div><div class="card stat"><span>RPE seduta</span><strong>${esc(w.summary?.rpe||'—')}</strong></div><div class="card stat"><span>Stato</span><strong style="color:var(--success)">Completata</strong></div></div>`:''}<h2 class="section-title">Programmato</h2>${(w.sections||[]).map(plannedSectionHtml).join('')}${w.summary?.notes?`<h2 class="section-title">Note finali</h2><div class="card">${esc(w.summary.notes).replace(/\n/g,'<br>')}</div>`:''}<div class="actions end" style="margin-top:18px"><button class="button danger small" data-action="delete-workout" data-id="${w.id}">Elimina allenamento</button></div>`)}
function renderWorkoutLog(id){const w=state.workouts.find(x=>x.id===id);if(!w)return setView('calendar');view.logDraft=JSON.parse(JSON.stringify(w));page(`<div class="page-head"><div><button class="button ghost small" data-action="open-workout" data-id="${w.id}">‹ Allenamento</button><h1 style="margin-top:10px">Registra svolto</h1><p class="muted">Mantieni il programmato e annota ciò che hai realmente eseguito.</p></div><button class="button" data-action="save-workout-log">Salva svolto</button></div>${view.logDraft.sections.map(logSectionHtml).join('')}<h2 class="section-title">Riepilogo seduta</h2><div class="card"><div class="form-grid two"><div class="field"><label>Durata totale</label><input id="logDuration" value="${esc(view.logDraft.summary?.duration||'')}" placeholder="Es. 1h 25' / 85 min"></div><div class="field"><label>RPE seduta (1-10)</label><input id="logRpe" type="number" min="1" max="10" value="${esc(view.logDraft.summary?.rpe||'')}"></div><div class="field full"><label>Note finali</label><textarea id="logNotes" placeholder="Come è andata la seduta?">${esc(view.logDraft.summary?.notes||'')}</textarea></div></div></div><div class="actions end" style="margin-top:16px"><button class="button ghost" data-action="open-workout" data-id="${w.id}">Annulla</button><button class="button" data-action="save-workout-log">Salva e completa</button></div>`);bindWorkoutLog()}
function logSectionHtml(s){let actual='';if(s.type==='strength'||s.type==='weightlifting'){actual=`<div class="list">${(s.rows||[]).map(r=>`<div class="actual-panel" data-log-row="${r.id}"><div class="checkline"><input type="checkbox" data-log-row-check="completed" ${r.completed?'checked':''}><strong>${esc(r.exercise||'Esercizio')}</strong><span class="muted tiny">programmato ${esc(r.sets||'—')}×${esc(r.reps||'—')}${r.load?` @ ${esc(r.load)}`:''}</span></div><div class="actual-grid" style="margin-top:8px"><div class="field"><label>Serie fatte</label><input data-log-row-field="actualSets" value="${esc(r.actualSets||'')}"></div><div class="field"><label>Rep fatte</label><input data-log-row-field="actualReps" value="${esc(r.actualReps||'')}"></div><div class="field"><label>Carico reale</label><input data-log-row-field="actualLoad" value="${esc(r.actualLoad||'')}" placeholder="kg"></div><div class="field"><label>Tentativi / note</label><input data-log-row-field="attempts" value="${esc(r.attempts||'')}" placeholder="100✓ 105✗ 105✓"></div></div></div>`).join('')}</div>`}
else if(s.type==='wod'){actual=`<div class="actual-panel"><div class="form-grid two"><div class="field"><label>Score</label><input data-log-sec-field="score" value="${esc(s.score||'')}" placeholder="Tempo / round+rep / reps / kg"></div><div class="field"><label>Livello</label><select data-log-sec-field="resultLevel"><option ${s.resultLevel==='Rx'?'selected':''}>Rx</option><option ${s.resultLevel==='Rx+'?'selected':''}>Rx+</option><option ${s.resultLevel==='Scaled'?'selected':''}>Scaled</option><option ${s.resultLevel==='Personalizzato'?'selected':''}>Personalizzato</option></select></div></div></div>`}
return `<section class="workout-section" data-log-section="${s.id}"><div class="section-head"><span class="section-emoji">${esc(s.emoji||'')}</span><strong>${esc(s.title)}</strong><label class="checkline"><input type="checkbox" data-log-sec-check="completed" ${s.completed?'checked':''}> Svolto</label></div><div class="section-body"><div class="planned-block">${plannedSectionBody(s)}</div>${actual}<div class="field" style="margin-top:9px"><label>Note svolto</label><textarea data-log-sec-field="actualNotes" placeholder="Modifiche, sensazioni, lavoro non completato...">${esc(s.actualNotes||'')}</textarea></div></div></section>`}
function plannedSectionBody(s){const html=plannedSectionHtml({...s,actualNotes:''});const m=html.match(/<div class="section-body planned-block">([\s\S]*)<\/div><\/section>$/);return m?m[1]:''}
function bindWorkoutLog(){const d=view.logDraft;document.querySelectorAll('[data-log-section]').forEach(el=>{const s=d.sections.find(x=>x.id===el.dataset.logSection);el.querySelectorAll('[data-log-sec-field]').forEach(f=>f.addEventListener('input',()=>s[f.dataset.logSecField]=f.value));el.querySelectorAll('[data-log-sec-check]').forEach(f=>f.addEventListener('change',()=>s[f.dataset.logSecCheck]=f.checked));el.querySelectorAll('[data-log-row]').forEach(re=>{const r=(s.rows||[]).find(x=>x.id===re.dataset.logRow);re.querySelectorAll('[data-log-row-field]').forEach(f=>f.addEventListener('input',()=>r[f.dataset.logRowField]=f.value));re.querySelectorAll('[data-log-row-check]').forEach(f=>f.addEventListener('change',()=>r[f.dataset.logRowCheck]=f.checked))})})}
async function saveWorkoutLog(){const d=view.logDraft;d.status='completed';d.completedAt=new Date().toISOString();d.summary={duration:document.getElementById('logDuration').value.trim(),rpe:document.getElementById('logRpe').value.trim(),notes:document.getElementById('logNotes').value.trim()};const ix=state.workouts.findIndex(x=>x.id===d.id);state.workouts[ix]=d;state.wodRecords=state.wodRecords.filter(r=>r.sourceWorkoutId!==d.id);for(const s of d.sections){if(s.type==='wod'&&s.score){state.wodRecords.push({id:uid('wrec'),sourceWorkoutId:d.id,sectionId:s.id,wodId:s.libraryId||'',wodName:s.name||s.title||'WOD',date:d.date,score:s.score,scoreType:s.scoreType||'time',level:s.resultLevel||s.level||'Rx',notes:s.actualNotes||''})}if(s.type==='strength'||s.type==='weightlifting'){for(const r of s.rows||[]){const kg=parseNum(r.actualLoad),reps=parseInt(r.actualReps||r.reps,10);if(kg>0&&reps>0){const prev=currentRecord(r.exercise,reps);if(!prev||kg>Number(prev.kg)){if(confirm(`Possibile nuovo PR: ${canonicalExercise(r.exercise)} ${reps}RM a ${kg} kg. Salvarlo nei massimali?`)){state.records.push({id:uid('rec'),exercise:canonicalExercise(r.exercise),reps,kg,date:d.date,source:'Allenamento',notes:`Da ${d.title}`})}}}}}}await save();setView('workout',{id:d.id});showToast('Seduta completata')}
function currentRecord(exercise,reps){const c=canonicalExercise(exercise).toLowerCase();return [...state.records].filter(r=>canonicalExercise(r.exercise).toLowerCase()===c&&Number(r.reps)===Number(reps)).sort((a,b)=>Number(b.kg)-Number(a.kg)||String(b.date).localeCompare(String(a.date)))[0]||null}

function renderProgress(){const lw=latestWeight(),records=[...state.records].sort((a,b)=>String(b.date).localeCompare(String(a.date))),pbs=wodPBs(),completed=state.workouts.filter(w=>w.status==='completed'),last30=completed.filter(w=>(parseISO(todayISO())-parseISO(w.date))/86400000<=30).length;page(`<div class="page-head"><div><h1>Progressi</h1><p class="muted">Peso, massimali, benchmark e frequenza di allenamento.</p></div><div class="actions"><button class="button secondary small" data-action="add-weight">＋ Peso</button><button class="button secondary small" data-action="add-record">＋ Massimale</button></div></div><div class="grid three"><div class="card stat"><span>Peso recente</span><strong>${lw?`${fmtNum(lw.kg)} kg`:'—'}</strong></div><div class="card stat"><span>PR registrati</span><strong>${records.length}</strong></div><div class="card stat"><span>Allenamenti ultimi 30 gg</span><strong>${last30}</strong></div></div><h2 class="section-title">Andamento peso</h2><div class="card chart-card"><canvas id="weightChart" width="900" height="260"></canvas><div class="legend"><span>Peso corporeo</span></div></div><h2 class="section-title">Massimali</h2>${records.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Esercizio</th><th>Record</th><th>Kg</th><th>Data</th><th></th></tr></thead><tbody>${records.map(r=>`<tr><td>${esc(r.exercise)}</td><td>${r.reps}RM</td><td><strong>${fmtNum(r.kg)}</strong></td><td>${fmtDate(r.date)}</td><td><button class="button ghost small" data-action="delete-record" data-id="${r.id}">Elimina</button></td></tr>`).join('')}</tbody></table></div>`:empty('🏆','Nessun massimale','Registra 1RM, 2RM, 3RM o qualsiasi altro record.')}<h2 class="section-title">Benchmark / WOD PB</h2>${pbs.length?`<div class="list">${pbs.slice(0,12).map(r=>`<div class="list-item"><div class="avatar">💥</div><div class="grow"><h3>${esc(r.wodName)}</h3><p>${esc(r.level)} · ${fmtDate(r.date)}</p></div><strong>${esc(r.score)}</strong></div>`).join('')}</div>`:empty('💥','Nessun WOD score','Quando completi un WOD con uno score, apparirà qui.')}`);setTimeout(drawWeightChart,30)}
function wodPBs(){const map=new Map();for(const r of state.wodRecords){const k=`${r.wodName}__${r.level}`;const p=map.get(k);if(!p||betterScore(r,p))map.set(k,r)}return [...map.values()].sort((a,b)=>String(b.date).localeCompare(String(a.date)))}
function betterScore(a,b){const t=a.scoreType||'time';if(t==='time'){const aa=parseTime(a.score),bb=parseTime(b.score);return aa!=null&&bb!=null?aa<bb:String(a.date)>String(b.date)}if(t==='rounds_plus_reps'){return parseRounds(a.score)>parseRounds(b.score)}const aa=parseNum(a.score),bb=parseNum(b.score);return Number.isFinite(aa)&&Number.isFinite(bb)?aa>bb:String(a.date)>String(b.date)}
function parseTime(s){const m=String(s||'').match(/(?:(\d+):)?(\d+):(\d+)/);if(m)return (+m[1]||0)*3600+(+m[2])*60+(+m[3]);const m2=String(s||'').match(/(\d+):(\d+)/);return m2?(+m2[1])*60+(+m2[2]):null} function parseRounds(s){const n=String(s||'').match(/(\d+)\D+(\d+)/);return n?(+n[1])*10000+(+n[2]):parseNum(s)||0}
function drawWeightChart(){const c=document.getElementById('weightChart');if(!c)return;const ctx=c.getContext('2d'),rows=[...state.weights].sort((a,b)=>a.date.localeCompare(b.date));const W=c.width,H=c.height,p=38;ctx.clearRect(0,0,W,H);ctx.strokeStyle='#d9e1df';ctx.lineWidth=1;for(let i=0;i<5;i++){const y=p+i*(H-2*p)/4;ctx.beginPath();ctx.moveTo(p,y);ctx.lineTo(W-p,y);ctx.stroke()}if(rows.length<2){ctx.fillStyle='#6f7d7e';ctx.font='18px sans-serif';ctx.fillText(rows.length?'Aggiungi un altro peso per vedere il grafico':'Nessun peso registrato',p,H/2);return}const vals=rows.map(r=>Number(r.kg)),min=Math.min(...vals)-1,max=Math.max(...vals)+1;ctx.strokeStyle='#d97145';ctx.lineWidth=4;ctx.lineJoin='round';ctx.beginPath();rows.forEach((r,i)=>{const x=p+i*(W-2*p)/(rows.length-1),y=H-p-(Number(r.kg)-min)/(max-min)*(H-2*p);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)});ctx.stroke();ctx.fillStyle='#0f2f33';rows.forEach((r,i)=>{const x=p+i*(W-2*p)/(rows.length-1),y=H-p-(Number(r.kg)-min)/(max-min)*(H-2*p);ctx.beginPath();ctx.arc(x,y,4,0,Math.PI*2);ctx.fill()})}

function renderCompetitions(){const future=state.competitions.filter(c=>daysUntil(c.date)>=0).sort((a,b)=>a.date.localeCompare(b.date)),past=state.competitions.filter(c=>daysUntil(c.date)<0).sort((a,b)=>b.date.localeCompare(a.date));page(`<div class="page-head"><div><h1>Gare</h1><p class="muted">Pesistica e competizioni CrossFit con più eventi.</p></div><button class="button" data-action="new-competition">＋ Gara</button></div><h2 class="section-title">Prossime gare</h2>${future.length?`<div class="list">${future.map(competitionCard).join('')}</div>`:empty('★','Nessuna gara futura','Inserisci la prossima competizione e il countdown comparirà nella Home.')}<h2 class="section-title">Gare passate</h2>${past.length?`<div class="list">${past.map(competitionCard).join('')}</div>`:'<p class="muted">Nessuna gara passata.</p>'}`)}
function competitionCard(c){return `<div class="card"><div class="page-head" style="margin-bottom:9px"><div><h3 style="margin:0">${esc(c.name)}</h3><p class="muted small">${fmtDate(c.date)} · ${c.type==='crossfit'?'CrossFit':'Pesistica'}${c.division?` · ${esc(c.division)}`:''}</p></div><span class="badge ${daysUntil(c.date)>=0?'accent':''}">${daysUntil(c.date)===0?'Oggi':daysUntil(c.date)>0?`${daysUntil(c.date)} gg`:`${Math.abs(daysUntil(c.date))} gg fa`}</span></div>${c.type==='weightlifting'&&c.result?`<p><strong>Risultato:</strong> ${esc(c.result)}</p>`:''}${c.type==='crossfit'&&c.events?.length?`<div class="chips">${c.events.map((e,i)=>`<span class="chip">E${i+1} ${esc(e.name||'Evento')}${e.score?` · ${esc(e.score)}`:''}</span>`).join('')}</div>`:''}<div class="actions" style="margin-top:10px"><button class="button secondary small" data-action="edit-competition" data-id="${c.id}">Modifica</button><button class="button danger small" data-action="delete-competition" data-id="${c.id}">Elimina</button></div></div>`}
function renderCompetitionEditor(id,date){const existing=id?state.competitions.find(c=>c.id===id):null;view.compDraft=existing?JSON.parse(JSON.stringify(existing)):{id:uid('comp'),name:'',date:date||todayISO(),type:'crossfit',division:'',location:'',result:'',notes:'',placement:'',events:[]};const d=view.compDraft;page(`<div class="page-head"><div><button class="button ghost small" data-nav="competitions">‹ Gare</button><h1 style="margin-top:10px">${existing?'Modifica gara':'Nuova gara'}</h1></div><button class="button" data-action="save-competition">Salva</button></div><div class="card"><div class="form-grid two"><div class="field"><label>Nome</label><input id="compName" value="${esc(d.name)}"></div><div class="field"><label>Data</label><input id="compDate" type="date" value="${d.date}"></div><div class="field"><label>Disciplina</label><select id="compType"><option value="crossfit" ${d.type==='crossfit'?'selected':''}>CrossFit</option><option value="weightlifting" ${d.type==='weightlifting'?'selected':''}>Pesistica</option></select></div><div class="field"><label>Luogo</label><input id="compLocation" value="${esc(d.location||'')}"></div></div></div><div id="compDetails" style="margin-top:12px">${competitionDetailsHtml(d)}</div><div class="actions end" style="margin-top:16px"><button class="button" data-action="save-competition">Salva gara</button></div>`);bindCompetitionEditor()}
function competitionDetailsHtml(d){if(d.type==='weightlifting')return `<div class="card"><div class="form-grid two"><div class="field"><label>Risultato</label><input id="compResult" value="${esc(d.result||'')}" placeholder="Es. 53 + 68 = 121 kg / 2° posto"></div><div class="field"><label>Note</label><textarea id="compNotes">${esc(d.notes||'')}</textarea></div></div></div>`;return `<div class="card"><div class="form-grid three"><div class="field"><label>Divisione</label><input id="compDivision" value="${esc(d.division||'')}" placeholder="Rx / Intermediate / Scaled"></div><div class="field"><label>Piazzamento finale</label><input id="compPlacement" value="${esc(d.placement||'')}"></div><div class="field"><label>Note</label><input id="compNotes" value="${esc(d.notes||'')}"></div></div></div><div class="page-head" style="margin-top:14px;margin-bottom:8px"><h2 class="section-title" style="margin:0">Eventi</h2><button class="button secondary small" data-action="add-comp-event">＋ Evento</button></div>${d.events.length?d.events.map((e,i)=>compEventHtml(e,i)).join(''):empty('＋','Nessun evento','Aggiungi gli eventi della competizione CrossFit.')}`}
function compEventHtml(e,i){return `<section class="workout-section" data-comp-event="${e.id}"><div class="section-head"><strong>Evento ${i+1}</strong><button class="button ghost small" data-action="remove-comp-event" data-id="${e.id}">✕</button></div><div class="section-body"><div class="form-grid three"><div class="field"><label>Nome</label><input data-event-field="name" value="${esc(e.name||'')}"></div><div class="field"><label>Formato</label><input data-event-field="format" value="${esc(e.format||'')}"></div><div class="field"><label>Piazzamento</label><input data-event-field="placement" value="${esc(e.placement||'')}"></div><div class="field full"><label>Workout</label><textarea data-event-field="workout">${esc(e.workout||'')}</textarea></div><div class="field"><label>Score</label><input data-event-field="score" value="${esc(e.score||'')}"></div><div class="field"><label>Note</label><input data-event-field="notes" value="${esc(e.notes||'')}"></div></div></div></section>`}
function bindCompetitionEditor(){const d=view.compDraft;['compName','compDate','compLocation'].forEach(id=>document.getElementById(id)?.addEventListener('input',e=>d[{compName:'name',compDate:'date',compLocation:'location'}[id]]=e.target.value));document.getElementById('compType').addEventListener('change',e=>{d.type=e.target.value;document.getElementById('compDetails').innerHTML=competitionDetailsHtml(d);bindCompetitionEditor()});document.getElementById('compResult')?.addEventListener('input',e=>d.result=e.target.value);document.getElementById('compDivision')?.addEventListener('input',e=>d.division=e.target.value);document.getElementById('compPlacement')?.addEventListener('input',e=>d.placement=e.target.value);document.getElementById('compNotes')?.addEventListener('input',e=>d.notes=e.target.value);document.querySelectorAll('[data-comp-event]').forEach(el=>{const ev=d.events.find(x=>x.id===el.dataset.compEvent);el.querySelectorAll('[data-event-field]').forEach(f=>f.addEventListener('input',()=>ev[f.dataset.eventField]=f.value))})}
async function saveCompetition(){const d=view.compDraft;if(!d.name.trim()){showToast('Inserisci il nome della gara');return}const ix=state.competitions.findIndex(c=>c.id===d.id);if(ix>=0)state.competitions[ix]=d;else state.competitions.push(d);await save();setView('competitions');showToast('Gara salvata')}

function renderProfile(){const p=state.profile,lw=latestWeight();page(`<div class="page-head"><div><h1>Profilo</h1><p class="muted">Un unico profilo personale per Pesistica + CrossFit.</p></div><button class="button secondary" data-action="edit-profile">Modifica</button></div><div class="card"><div class="list-item" style="border:0;padding:0"><div class="avatar">${esc((p.firstName?.[0]||'T')+(p.lastName?.[0]||'J'))}</div><div class="grow"><h2 style="margin:0">${esc(name())}</h2><p>${p.birthDate?`${age(p.birthDate)} anni · `:''}${p.sex==='female'?'Femminile':'Maschile'} · Pesistica + CrossFit</p></div></div></div><div class="grid three" style="margin-top:12px"><div class="card stat"><span>Peso recente</span><strong>${lw?`${fmtNum(lw.kg)} kg`:'—'}</strong></div><div class="card stat"><span>Massimali</span><strong>${state.records.length}</strong></div><div class="card stat"><span>WOD personali</span><strong>${state.personalWods.length}</strong></div></div><h2 class="section-title">Archivio e backup</h2><div class="card"><p class="muted small" style="margin-top:0">I dati sono salvati sul dispositivo con IndexedDB. Esporta periodicamente una copia in File/iCloud Drive.</p><div class="actions"><button class="button" data-action="export-backup">Esporta backup</button><button class="button secondary" data-action="import-backup">Ripristina backup</button></div></div><h2 class="section-title">Libreria incorporata</h2><div class="card"><strong>${WODS.length.toLocaleString('it-IT')} WOD</strong><p class="muted small">Benchmark, Hero, Open e archivio Hybrid/Hyrox già disponibili offline.</p><div class="chips">${categoryCounts().slice(0,8).map(([k,v])=>`<span class="chip">${esc(k)} · ${v}</span>`).join('')}</div></div><h2 class="section-title">Sincronizzazione futura</h2><div class="card"><span class="badge">Predisposta</span><p class="muted small">Gli identificativi dei dati sono già separati per collegare in seguito Training Journal a Weightlifting Coach via Firebase.</p></div><div class="card" style="margin-top:12px;border-color:#efd0d0"><h3 style="margin-top:0">Zona dati</h3><button class="button danger small" data-action="reset-data">Cancella diario</button></div>`)}
function categoryCounts(){const m=new Map();WODS.forEach(w=>m.set(w.category||'Altro',(m.get(w.category||'Altro')||0)+1));return [...m.entries()].sort((a,b)=>b[1]-a[1])}

function showProfileForm(){const p=state.profile;openModal('Modifica profilo',`<form id="profileForm" class="form-grid two"><div class="field"><label>Nome</label><input name="firstName" required value="${esc(p.firstName||'')}"></div><div class="field"><label>Cognome</label><input name="lastName" required value="${esc(p.lastName||'')}"></div><div class="field"><label>Data di nascita</label><input name="birthDate" type="date" value="${esc(p.birthDate||'')}"></div><div class="field"><label>Sesso</label><select name="sex"><option value="female" ${p.sex==='female'?'selected':''}>Femminile</option><option value="male" ${p.sex==='male'?'selected':''}>Maschile</option></select></div><div class="field full"><span class="badge accent">Pesistica + CrossFit</span></div><div class="field full"><button class="button" type="submit">Salva profilo</button></div></form>`);document.getElementById('profileForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);Object.assign(state.profile,{firstName:String(f.get('firstName')||'').trim(),lastName:String(f.get('lastName')||'').trim(),birthDate:String(f.get('birthDate')||''),sex:String(f.get('sex')||'female'),discipline:'both'});await save();closeModal();render();showToast('Profilo aggiornato')})}
function showWeightForm(date=todayISO()){openModal('Registra peso',`<form id="weightForm" class="form-grid two"><div class="field"><label>Peso corporeo</label><input name="kg" type="number" step="0.1" min="1" required placeholder="kg"></div><div class="field"><label>Data</label><input name="date" type="date" required value="${date}"></div><div class="field full"><label>Nota</label><input name="notes" placeholder="Facoltativa"></div><div class="field full"><button class="button" type="submit">Salva peso</button></div></form>`);document.getElementById('weightForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);state.weights.push({id:uid('weight'),kg:Number(f.get('kg')),date:String(f.get('date')),notes:String(f.get('notes')||'')});await save();closeModal();render();showToast('Peso registrato')})}
function showRecordForm(date=todayISO()){openModal('Aggiungi massimale',`<form id="recordForm" class="form-grid two"><div class="field full"><label>Esercizio</label><input name="exercise" data-exercise-input required placeholder="Cerca o scrivi liberamente"></div><div class="field"><label>RM</label><input name="reps" type="number" min="1" required value="1"></div><div class="field"><label>Peso</label><input name="kg" type="number" step="0.5" min="0.5" required></div><div class="field"><label>Data</label><input name="date" type="date" value="${date}" required></div><div class="field"><label>Origine</label><select name="source"><option>Allenamento</option><option>Test</option><option>Gara</option></select></div><div class="field full"><label>Note</label><input name="notes"></div><div class="field full"><button class="button" type="submit">Salva massimale</button></div></form>`);bindExerciseSuggestions(modalBody);document.getElementById('recordForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);state.records.push({id:uid('rec'),exercise:canonicalExercise(f.get('exercise')),reps:Number(f.get('reps')),kg:Number(f.get('kg')),date:String(f.get('date')),source:String(f.get('source')),notes:String(f.get('notes')||'')});await save();closeModal();render();showToast('Massimale salvato')})}
function showWodLibrary(secId){const personal=state.personalWods.map(p=>({id:p.id,name:p.name,category:'Personale',format:p.format,scoreType:p.scoreType,description:p.description,searchText:p.searchText||`${p.name} ${p.format} ${p.description}`}));view.wodTargetSec=secId;openModal('Libreria WOD',`<div class="field"><label>Cerca per nome, formato, movimento o categoria</label><input id="wodSearch" placeholder="Es. Fran, Hero, EMOM, burpee..."></div><div id="wodResults" style="margin-top:10px"></div>`,`Libreria incorporata: ${WODS.length.toLocaleString('it-IT')} WOD + ${personal.length} personali`);const inp=document.getElementById('wodSearch');const renderResults=()=>{const q=inp.value.trim().toLowerCase();const src=[...personal,...WODS];let rows=q?src.filter(w=>String(w.searchText||`${w.name} ${w.category} ${w.format} ${w.description}`).toLowerCase().includes(q)):src.filter(w=>['Benchmark','Hero','Open'].includes(w.category)).slice(0,30);rows=rows.slice(0,50);document.getElementById('wodResults').innerHTML=rows.length?rows.map(w=>`<div class="wod-card"><div class="page-head" style="margin:0"><div><h4>${esc(w.name)}</h4><span class="badge">${esc(w.category||'Altro')}</span> ${w.format?`<span class="badge">${esc(w.format)}</span>`:''}</div><button class="button small" data-action="import-wod" data-id="${esc(w.id)}" data-personal="${w.category==='Personale'?'1':'0'}">Importa</button></div><pre>${esc((w.description||'').slice(0,650))}</pre></div>`).join(''):empty('🔎','Nessun WOD','Prova con un altro termine di ricerca.');};inp.addEventListener('input',renderResults);renderResults()}
function importWod(id,personal){const src=personal?state.personalWods.find(x=>x.id===id):WODS.find(x=>x.id===id);const sec=view.draft?.sections.find(x=>x.id===view.wodTargetSec);if(!src||!sec)return;sec.name=src.name||'';sec.format=src.format||'';sec.text=src.description||'';sec.scoreType=src.scoreType||'time';sec.libraryId=personal?'':src.id;closeModal();rerenderDraftSections();showToast('WOD importato')}

function workoutMessage(w,done=false){const lines=[`*${w.title}*`,fmtLong(w.date),''];for(const s of w.sections||[]){lines.push(`${s.emoji||''} *${String(s.title||'').toUpperCase()}*`);lines.push(stripHtml(plannedSectionBody(s)));if(done){if(s.type==='strength'||s.type==='weightlifting'){for(const r of s.rows||[]){if(r.actualLoad||r.actualReps)lines.push(`Svolto: ${r.exercise} ${r.actualSets||r.sets||'—'}×${r.actualReps||r.reps||'—'}${r.actualLoad?` @ ${r.actualLoad} kg`:''}${r.attempts?` · ${r.attempts}`:''}`)}}if(s.type==='wod'&&s.score)lines.push(`Score: ${s.score} · ${s.resultLevel||s.level||'Rx'}`);if(s.actualNotes)lines.push(`Note: ${s.actualNotes}`)}lines.push('')}if(done&&w.summary){if(w.summary.duration)lines.push(`Durata: ${w.summary.duration}`);if(w.summary.rpe)lines.push(`RPE seduta: ${w.summary.rpe}/10`);if(w.summary.notes)lines.push(`Note finali: ${w.summary.notes}`)}return lines.join('\n').replace(/\n{3,}/g,'\n\n').trim()}
function stripHtml(html){const d=document.createElement('div');d.innerHTML=html;return d.innerText.trim()}
async function shareText(text){if(navigator.share){try{await navigator.share({text});return}catch(e){if(e.name==='AbortError')return}}await navigator.clipboard.writeText(text);showToast('Testo copiato')}
async function exportBackup(){const payload={app:'Training Journal',version:VERSION,exportedAt:new Date().toISOString(),data:state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),file=new File([blob],`TrainingJournal_backup_${todayISO()}.json`,{type:'application/json'});if(navigator.canShare&&navigator.canShare({files:[file]})){try{await navigator.share({files:[file],title:'Backup Training Journal'});return}catch(e){if(e.name==='AbortError')return}}const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function importBackupFile(file){try{const parsed=JSON.parse(await file.text()),data=parsed.data||parsed;if(!data.profile||!Array.isArray(data.workouts))throw new Error('Formato non riconosciuto');if(!confirm('Sostituire il diario attuale con questo backup?'))return;state=normalize(data);await save();setView('home');showToast('Backup ripristinato')}catch(e){showToast(`Backup non valido: ${e.message}`)}}
function fmtNum(v){const n=Number(v);return Number.isFinite(n)?(Number.isInteger(n)?String(n):n.toFixed(1).replace('.',',')):'—'} function parseNum(v){const m=String(v||'').replace(',','.').match(/-?\d+(?:\.\d+)?/);return m?Number(m[0]):NaN}

suggestions.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-suggestion]');if(b&&activeSuggestionInput){e.preventDefault();activeSuggestionInput.value=b.dataset.suggestion;activeSuggestionInput.dispatchEvent(new Event('input',{bubbles:true}));hideSuggestions()}});
document.getElementById('modalClose').addEventListener('click',closeModal);modalBackdrop.addEventListener('click',e=>{if(e.target===modalBackdrop)closeModal()});backupInput.addEventListener('change',e=>{const f=e.target.files?.[0];if(f)importBackupFile(f);backupInput.value=''});
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-nav]');if(nav){setView(nav.dataset.nav);return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
if(a==='new-workout')return setView('workout-edit',{date:b.dataset.date||todayISO()});if(a==='edit-workout')return setView('workout-edit',{id:b.dataset.id});if(a==='open-workout')return setView('workout',{id:b.dataset.id});if(a==='log-workout')return setView('workout-log',{id:b.dataset.id});if(a==='open-day')return setView('day',{date:b.dataset.date});if(a==='cancel-workout-edit')return setView('calendar');if(a==='save-workout')return saveWorkoutDraft();if(a==='save-workout-log')return saveWorkoutLog();
if(a==='workout-template'){if(view.draft.sections.length&&!confirm('Sostituire le sezioni attuali con questo modello?'))return;view.draft.sections=templateSections(b.dataset.template);return rerenderDraftSections()}if(a==='add-section'){view.draft.sections.push(newSection(document.getElementById('sectionType').value));return rerenderDraftSections()}if(a==='section-up'||a==='section-down'){const i=view.draft.sections.findIndex(x=>x.id===b.dataset.sec),j=a==='section-up'?i-1:i+1;if(i>=0&&j>=0&&j<view.draft.sections.length)[view.draft.sections[i],view.draft.sections[j]]=[view.draft.sections[j],view.draft.sections[i]];return rerenderDraftSections()}if(a==='section-delete'){view.draft.sections=view.draft.sections.filter(x=>x.id!==b.dataset.sec);return rerenderDraftSections()}if(a==='add-simple-row'){const s=view.draft.sections.find(x=>x.id===b.dataset.sec);s.rows.push({id:uid('row'),exercise:'',reps:'',note:''});return rerenderDraftSections()}if(a==='add-lift-row'){const s=view.draft.sections.find(x=>x.id===b.dataset.sec);s.rows.push(newLiftRow());return rerenderDraftSections()}if(a==='remove-row'){const secEl=b.closest('[data-section-id]'),rowEl=b.closest('[data-row-id]'),s=view.draft.sections.find(x=>x.id===secEl.dataset.sectionId);s.rows=s.rows.filter(x=>x.id!==rowEl.dataset.rowId);return rerenderDraftSections()}if(a==='add-tabata-item'){view.draft.sections.find(x=>x.id===b.dataset.sec).items.push('');return rerenderDraftSections()}if(a==='remove-tabata-item'){const s=view.draft.sections.find(x=>x.id===b.dataset.sec);s.items.splice(Number(b.dataset.index),1);return rerenderDraftSections()}if(a==='open-wod-library')return showWodLibrary(b.dataset.sec);if(a==='import-wod')return importWod(b.dataset.id,b.dataset.personal==='1');
if(a==='share-workout'){const w=state.workouts.find(x=>x.id===b.dataset.id);return shareText(workoutMessage(w,b.dataset.mode==='done'))}if(a==='delete-workout'){if(!confirm('Eliminare questo allenamento?'))return;state.workouts=state.workouts.filter(x=>x.id!==b.dataset.id);state.wodRecords=state.wodRecords.filter(x=>x.sourceWorkoutId!==b.dataset.id);await save();return setView('calendar')}
if(a==='cal-prev'){calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()-1,1,12);return renderCalendar()}if(a==='cal-next'){calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()+1,1,12);return renderCalendar()}
if(a==='add-weight')return showWeightForm(b.dataset.date||view.date||todayISO());if(a==='add-record')return showRecordForm(b.dataset.date||view.date||todayISO());if(a==='delete-record'){if(!confirm('Eliminare questo massimale?'))return;state.records=state.records.filter(x=>x.id!==b.dataset.id);await save();return render()}
if(a==='toggle-rest'){const date=b.dataset.date,ex=state.rests.find(x=>x.date===date);if(ex)state.rests=state.rests.filter(x=>x.id!==ex.id);else state.rests.push({id:uid('rest'),date,notes:''});await save();return renderDay(date)}
if(a==='new-competition')return setView('competition-edit',{date:b.dataset.date||todayISO()});if(a==='edit-competition')return setView('competition-edit',{id:b.dataset.id});if(a==='save-competition')return saveCompetition();if(a==='add-comp-event'){view.compDraft.events.push({id:uid('event'),name:'',format:'',workout:'',score:'',placement:'',notes:''});document.getElementById('compDetails').innerHTML=competitionDetailsHtml(view.compDraft);return bindCompetitionEditor()}if(a==='remove-comp-event'){view.compDraft.events=view.compDraft.events.filter(x=>x.id!==b.dataset.id);document.getElementById('compDetails').innerHTML=competitionDetailsHtml(view.compDraft);return bindCompetitionEditor()}if(a==='delete-competition'){if(!confirm('Eliminare questa gara?'))return;state.competitions=state.competitions.filter(x=>x.id!==b.dataset.id);await save();return renderCompetitions()}
if(a==='edit-profile')return showProfileForm();if(a==='export-backup')return exportBackup();if(a==='import-backup')return backupInput.click();if(a==='reset-data'){if(!confirm('Cancellare definitivamente tutto il diario?'))return;if(!confirm('Conferma finale: esporta prima un backup se vuoi conservare i dati.'))return;state=freshState();await save();return setView('home')}
});

async function init(){try{state=normalize(await TJDB.get(STATE_KEY));await save()}catch(e){console.error(e);state=freshState();showToast('Archivio locale inizializzato')}if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').catch(()=>{})}window.addEventListener('online',updateOnline);window.addEventListener('offline',updateOnline);updateOnline();render();if(!state.profile.firstName)setTimeout(showProfileForm,350)}
function updateOnline(){const el=document.getElementById('offlineBadge');if(el)el.textContent=navigator.onLine?'Online · offline ready':'Offline'}
init();
})();
